<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage } from 'element-plus'
import ApprovalDecisionDialog from '../../../components/team/ApprovalDecisionDialog.vue'
import { approveTeamRegistration, createTeamIdempotencyKey, getTeam, getTeamErrorMessage, listTeamMembers, listTeams } from '../../../api/team'
import type { ApprovalDecision, TeamDetail, TeamMember, TeamPageItem, TeamStatus } from '../../../types/team'
import { TEAM_STATUS_LABELS, TEAM_STATUS_TAG_TYPES } from '../../../types/team'
const route = useRoute()
const editionId = computed(() => String(route.query.edition_id ?? ''))
const loading = ref(false); const teams = ref<TeamPageItem[]>([]); const total = ref(0); const page = ref(1); const size = ref(10); const filters = reactive({ keyword: '', teacher_id: '' })
const drawerVisible = ref(false); const detailLoading = ref(false); const detail = ref<TeamDetail | null>(null); const members = ref<TeamMember[]>([])
const dialogVisible = ref(false); const decision = ref<ApprovalDecision>('APPROVE'); const submitting = ref(false); const canAct = computed(() => detail.value?.status === 'PENDING_ADMIN')
async function load(): Promise<void> { if (!editionId.value) return; loading.value = true; try { const data = await listTeams(editionId.value, { page: page.value, size: size.value, status: 'PENDING_ADMIN', keyword: filters.keyword.trim() || undefined, teacher_id: filters.teacher_id.trim() || undefined, sort: '-created_at' }); teams.value = data.items; total.value = data.total } catch (error) { ElMessage.error(getTeamErrorMessage(error, '待终审队伍加载失败')) } finally { loading.value = false } }
async function openReview(row: TeamPageItem): Promise<void> { drawerVisible.value = true; detailLoading.value = true; detail.value = null; members.value = []; try { const [team, memberList] = await Promise.all([getTeam(row.id), listTeamMembers(row.id)]); detail.value = team; members.value = memberList } catch (error) { ElMessage.error(getTeamErrorMessage(error, '队伍详情加载失败')); drawerVisible.value = false } finally { detailLoading.value = false } }
async function reloadDetail(): Promise<void> { if (!detail.value) return; const currentId = detail.value.id; try { const [team, memberList] = await Promise.all([getTeam(currentId), listTeamMembers(currentId)]); detail.value = team; members.value = memberList } catch (error) { ElMessage.error(getTeamErrorMessage(error, '队伍详情刷新失败')); drawerVisible.value = false } }
function openDecision(value: ApprovalDecision): void { if (!canAct.value) { ElMessage.warning('队伍状态已变化，请刷新后重试'); return } decision.value = value; dialogVisible.value = true }
async function confirmDecision(reason: string): Promise<void> { if (!detail.value || detail.value.current_registration_version === null) { ElMessage.warning('当前报名轮次版本缺失，请刷新'); return } submitting.value = true; try { await approveTeamRegistration(detail.value.id, { stage: 'ADMIN', decision: decision.value, reason: reason || undefined, version: detail.value.current_registration_version }, createTeamIdempotencyKey()); ElMessage.success(decision.value === 'APPROVE' ? '终审已通过' : '报名已驳回'); dialogVisible.value = false; drawerVisible.value = false; await load() } catch (error) { ElMessage.error(getTeamErrorMessage(error, '管理员终审失败')); await load(); await reloadDetail() } finally { submitting.value = false } }
function search(): void { page.value = 1; void load() }
onMounted(load)
</script>
<template>
  <div class="admin-team-page">
    <section class="hero-card"><div><span class="eyebrow">ADMIN FINAL REVIEW</span><h1>报名终审</h1><p>审核教师已确认的队伍，复核报名资格、成员快照与学校名额。</p></div><el-tag size="large" effect="plain">{{ total }} 支待终审</el-tag></section>
    <el-alert v-if="!editionId" type="warning" :closable="false" show-icon title="缺少届次参数" description="请携带 edition_id 进入管理员终审页。" />
    <el-card v-else>
      <el-form inline class="filters"><el-form-item label="队伍"><el-input v-model="filters.keyword" clearable placeholder="队伍名称或编码" @keyup.enter="search" /></el-form-item><el-form-item label="教师 ID"><el-input v-model="filters.teacher_id" clearable placeholder="指导教师 ID" @keyup.enter="search" /></el-form-item><el-form-item><el-button type="primary" @click="search">查询</el-button></el-form-item></el-form>
      <el-table v-loading="loading" :data="teams" border row-key="id"><el-table-column prop="team_name" label="队伍名称" min-width="220" /><el-table-column prop="team_code" label="队伍编码" width="150" /><el-table-column prop="member_count" label="人数" width="80" /><el-table-column label="状态" width="130"><template #default="{ row }"><el-tag :type="TEAM_STATUS_TAG_TYPES[row.status as TeamStatus]" effect="plain">{{ TEAM_STATUS_LABELS[row.status as TeamStatus] }}</el-tag></template></el-table-column><el-table-column label="操作" width="120"><template #default="{ row }"><el-button link type="primary" @click="openReview(row)">终审</el-button></template></el-table-column></el-table>
      <div class="pagination"><el-pagination v-model:current-page="page" v-model:page-size="size" :total="total" layout="total, prev, pager, next" background @current-change="load" /></div>
    </el-card>
    <el-drawer v-model="drawerVisible" title="管理员终审" size="min(760px, 94vw)" destroy-on-close><div v-loading="detailLoading" class="drawer-body"><template v-if="detail"><div class="team-summary"><div><h2>{{ detail.team_name }}</h2><p>{{ detail.team_code }} · {{ detail.member_count }} 人</p></div><el-tag :type="TEAM_STATUS_TAG_TYPES[detail.status]">{{ TEAM_STATUS_LABELS[detail.status] }}</el-tag></div><el-alert :type="detail.can_register ? 'success' : 'warning'" :closable="false" show-icon :title="detail.can_register ? '资格复核可报名' : '资格复核不通过'" :description="detail.register_reason || detail.register_state || '无补充说明'" /><el-descriptions :column="2" border class="facts"><el-descriptions-item label="指导教师">{{ detail.current_teacher_name || '未确认' }}</el-descriptions-item><el-descriptions-item label="轮次版本">{{ detail.current_registration_version }}</el-descriptions-item><el-descriptions-item label="教师申请">{{ detail.current_teacher_application_status || '无' }}</el-descriptions-item></el-descriptions><el-table :data="members" border class="member-table"><el-table-column prop="member_name" label="姓名" /><el-table-column prop="school_id" label="学校 ID" /><el-table-column prop="student_no" label="学号" /><el-table-column label="身份" width="90"><template #default="{ row }"><el-tag v-if="row.is_leader" type="warning">队长</el-tag><span v-else>队员</span></template></el-table-column></el-table><div v-if="canAct" class="drawer-actions"><el-button type="danger" plain @click="openDecision('REJECT')">驳回</el-button><el-button type="primary" @click="openDecision('APPROVE')">通过终审</el-button></div></template></div></el-drawer>
    <ApprovalDecisionDialog v-if="detail" v-model="dialogVisible" stage="ADMIN" :decision="decision" :team-name="detail.team_name" :version="detail.current_registration_version ?? 0" :submitting="submitting" @confirm="confirmDecision" />
  </div>
</template>
<style scoped>
.admin-team-page { display: grid; gap: 16px; padding: 18px; }.hero-card { display: flex; align-items: center; justify-content: space-between; gap: 24px; padding: 28px 30px; border-radius: 18px 18px 18px 5px; color: #f0f5f1; background: radial-gradient(circle at 90% 10%, rgba(216,186,112,.34), transparent 16rem), linear-gradient(135deg, #143b31, #275b4b); }.hero-card h1 { margin: 7px 0 8px; font-family: Georgia, "Songti SC", serif; font-size: 32px; font-weight: 500; }.hero-card p { margin: 0; color: rgba(240,245,241,.72); }.eyebrow { color: #d8ba70; font-size: 11px; font-weight: 700; letter-spacing: .16em; }.filters { margin-bottom: 4px; }.pagination { display: flex; justify-content: flex-end; margin-top: 18px; }.facts, .member-table { margin-top: 16px; }.team-summary { display: flex; align-items: center; justify-content: space-between; gap: 16px; margin-bottom: 16px; }.team-summary h2 { margin: 0 0 5px; }.team-summary p { margin: 0; color: #74877f; }.drawer-actions { display: flex; justify-content: flex-end; gap: 10px; margin-top: 22px; }
</style>
